description:
A game passes its players around by pointer, so every system changes the same `Player`:

```cpp
struct Player
{
    int health;
    int maxHealth;
    int armour;
};

void damage(Player* p, int amount);
void heal(Player* p, int amount);
void healBoth(Player* a, Player* b, int amount);
int totalHealth(const Player* a, const Player* b);
```

- **damage**: armour soaks up damage first and is used up by it; whatever is left comes off health, which never goes below 0. Damage of 0 or less does nothing.
- **heal** adds to health, but never above `maxHealth`. Healing of 0 or less does nothing.
- **healBoth** heals both players. If `a` and `b` are the **same** player, it is healed only once.
- **totalHealth** adds up both players' health; if both pointers are the same player, it is counted once. It takes `const Player*` because it only reads.

All four use `->` to reach the members.

starter.solution.cpp:
struct Player
{
    int health;
    int maxHealth;
    int armour;
};

void damage(Player* p, int amount) {}
void heal(Player* p, int amount) {}
void healBoth(Player* a, Player* b, int amount) {}
int totalHealth(const Player* a, const Player* b) { return 0; }

solution.solution.cpp:
struct Player
{
    int health;
    int maxHealth;
    int armour;
};

void damage(Player* p, int amount)
{
    if (amount <= 0) return;
    const int soaked{ amount < p->armour ? amount : p->armour };
    p->armour -= soaked;
    amount -= soaked;
    p->health -= amount;
    if (p->health < 0) p->health = 0;
}

void heal(Player* p, int amount)
{
    if (amount <= 0) return;
    p->health += amount;
    if (p->health > p->maxHealth) p->health = p->maxHealth;
}

void healBoth(Player* a, Player* b, int amount)
{
    heal(a, amount);
    if (b != a) heal(b, amount);
}

int totalHealth(const Player* a, const Player* b)
{
    return a == b ? a->health : a->health + b->health;
}

unitTests:
TEST("armour first, then health") {
    Player p{ 100, 100, 30 };
    damage(&p, 20);
    CHECK_EQ(p.armour, 10); CHECK_EQ(p.health, 100);
    damage(&p, 25);
    CHECK_EQ(p.armour, 0); CHECK_EQ(p.health, 85);
    damage(&p, 500);
    CHECK_EQ(p.health, 0);
    damage(&p, -10);
    CHECK_EQ(p.health, 0);
}
TEST("healing stops at the maximum") {
    Player p{ 40, 100, 0 };
    heal(&p, 25); CHECK_EQ(p.health, 65);
    heal(&p, 100); CHECK_EQ(p.health, 100);
    heal(&p, -50); CHECK_EQ(p.health, 100);
}
TEST("two players") {
    Player a{ 10, 100, 0 }, b{ 50, 60, 0 };
    healBoth(&a, &b, 20);
    CHECK_EQ(a.health, 30); CHECK_EQ(b.health, 60);
    CHECK_EQ(totalHealth(&a, &b), 90);
}
TEST("the same player twice") {
    Player a{ 10, 100, 0 };
    healBoth(&a, &a, 20);
    CHECK_EQ(a.health, 30);
    CHECK_EQ(totalHealth(&a, &a), 30);
}

